def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                edge |= y == 0 or x == 0 or y == h-1 or x == w-1
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
